import{_ as a,o as t,c as o,a3 as d}from"./chunks/framework.B8xISX-C.js";const f=JSON.parse('{"title":"applications","description":"","frontmatter":{},"headers":[],"relativePath":"reference/applications.md","filePath":"reference/applications.md"}'),i={name:"reference/applications.md"};function s(c,e,r,l,n,p){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="applications" tabindex="-1">applications <a class="header-anchor" href="#applications" aria-label="Permalink to &quot;applications&quot;">​</a></h1><p>One application of a research field: what the player picks when the field completes. Weapons, buildings, armour and other items name the application that unlocks them.</p><p>A mod adds records in <code>records/applications/&lt;file&gt;.json</code> (<code>{ &quot;$schema&quot;: &quot;carina-records/1&quot;, &quot;catalog&quot;: &quot;applications&quot;, &quot;records&quot;: [...] }</code>) and changes base records with patch rows on catalog <code>applications</code>. Schema: <a href="/carina-mod-template/schemas/records/applications.schema.json">applications records schema</a>.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><p>A mod record leaves out <code>id</code> and <code>prov</code>: the game assigns ids, and <code>prov</code> is the project&#39;s own provenance.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><span id="f-key" class="field-name"><code>key</code></span><a class="field-link" href="#f-key" aria-label="Link to key">#</a></td><td><code>&lt;namespace&gt;.&lt;snake_case&gt;</code>: your package id with <code>-</code> read as <code>_</code>, then a name</td><td>yes</td><td></td></tr><tr><td><span id="f-field" class="field-name"><code>field</code></span><a class="field-link" href="#f-field" aria-label="Link to field">#</a></td><td>key of a record in <code>tech-fields</code>, or null</td><td>yes</td><td>the key of its tech field</td></tr><tr><td><span id="f-aiGroup" class="field-name"><code>aiGroup</code></span><a class="field-link" href="#f-aiGroup" aria-label="Link to aiGroup">#</a></td><td>integer 0..41</td><td>yes</td><td>the AI research valuation group</td></tr><tr><td><span id="f-inStrategic" class="field-name"><code>inStrategic</code></span><a class="field-link" href="#f-inStrategic" aria-label="Link to inStrategic">#</a></td><td>true or false</td><td>yes</td><td>shown in the strategic (auto-resolve) combat summary</td></tr><tr><td><span id="f-nameKey" class="field-name"><code>nameKey</code></span><a class="field-link" href="#f-nameKey" aria-label="Link to nameKey">#</a></td><td>text key</td><td>yes</td><td></td></tr><tr><td><span id="f-descKey" class="field-name"><code>descKey</code></span><a class="field-link" href="#f-descKey" aria-label="Link to descKey">#</a></td><td>text key</td><td>yes</td><td></td></tr><tr><td><span id="f-relayRangePc" class="field-name"><code>relayRangePc</code></span><a class="field-link" href="#f-relayRangePc" aria-label="Link to relayRangePc">#</a></td><td>integer &gt;= 1 or null</td><td>no</td><td></td></tr></tbody></table><p>References to other records are written as keys; the game turns them into ids.</p><h2 id="also-register-it-in" tabindex="-1">Also register it in <a class="header-anchor" href="#also-register-it-in" aria-label="Permalink to &quot;Also register it in&quot;">​</a></h2><ul><li>the item it unlocks names it: <code>application</code> (weapons, buildings) or <code>app</code> (armor, shields, computers, drives, fuel-cells, specials)</li></ul><h2 id="computer-players" tabindex="-1">Computer players <a class="header-anchor" href="#computer-players" aria-label="Permalink to &quot;Computer players&quot;">​</a></h2><p>Valued through <code>aiGroup</code> (one of the groups the AI&#39;s research valuation knows); pick the group of the closest base application.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>At most four applications per field: the research screen shows four choices (<code>research-grid-capacity</code>).</li><li><code>aiGroup</code> is 0 to 41.</li><li>An application has no effect of its own; its effect comes from what it unlocks, or from a colony-economy <code>sources</code> row.</li><li>To suppress a base application, <code>remove</code> it: the compile lists every record and rule row still built on it (<code>removed-dependent</code>), which the mod removes or repoints in the same package.</li></ul><h2 id="patch-paths" tabindex="-1">Patch paths <a class="header-anchor" href="#patch-paths" aria-label="Permalink to &quot;Patch paths&quot;">​</a></h2><p>Rows on this catalog address a record by <code>key</code> and a field by <code>path</code>:</p><ul><li><code>set</code>: <code>aiGroup</code>, <code>descKey</code>, <code>field</code>, <code>inStrategic</code>, <code>nameKey</code>, <code>relayRangePc</code></li><li><code>append</code>, <code>insertAfter</code>, <code>removeValue</code>: none (no list fields)</li></ul>',16)])])}const u=a(i,[["render",s]]);export{f as __pageData,u as default};
